// Modified by Post-Step 10 audit: 顶层持有 SettingsViewModel，避免 NavBackStackEntry 作用域造成主题不同步
package com.example.kyrgyzkeyboard

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.NavigationBar
import androidx.compose.material3.NavigationBarItem
import androidx.compose.material3.Scaffold
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.res.stringResource
import androidx.hilt.navigation.compose.hiltViewModel
import androidx.navigation.NavDestination.Companion.hierarchy
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.compose.rememberNavController
import com.example.kyrgyzkeyboard.data.model.KeyboardSettings
import com.example.kyrgyzkeyboard.ui.dictionary.DictionaryScreen
import com.example.kyrgyzkeyboard.ui.preview.PreviewScreen
import com.example.kyrgyzkeyboard.ui.settings.SettingsScreen
import com.example.kyrgyzkeyboard.ui.settings.SettingsViewModel
import com.example.kyrgyzkeyboard.ui.theme.KyrgyzKeyboardTheme
import dagger.hilt.android.AndroidEntryPoint

/**
 * 应用主 Activity：仅承担导航宿主，无业务逻辑。
 * 底部 3 个 Tab：预览 / 词库 / 设置。
 */
@AndroidEntryPoint
class MainActivity : ComponentActivity() {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent { AppRoot() }
    }
}

private object Routes {
    const val PREVIEW = "preview"
    const val DICTIONARY = "dictionary"
    const val SETTINGS = "settings"
}

private data class TabItem(val route: String, val labelRes: Int, val icon: String)

private val TABS = listOf(
    TabItem(Routes.PREVIEW, R.string.tab_preview, "\u2328"),               // ⌨
    TabItem(Routes.DICTIONARY, R.string.dictionary_title, "\uD83D\uDCD6"), // 📖
    TabItem(Routes.SETTINGS, R.string.settings_title, "\u2699")            // ⚙
)

@Composable
private fun AppRoot() {
    // 在 Activity 作用域拿到 SettingsViewModel，避免 NavBackStackEntry 重新作用域化
    val settingsVm: SettingsViewModel = hiltViewModel()
    val settings by settingsVm.settings.collectAsState()
    val systemDark = isSystemInDarkTheme()
    val darkTheme = when (settings.theme) {
        KeyboardSettings.THEME_DARK -> true
        KeyboardSettings.THEME_LIGHT -> false
        else -> systemDark
    }
    KyrgyzKeyboardTheme(darkTheme = darkTheme) {
        AppScaffold(settingsVm = settingsVm)
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun AppScaffold(settingsVm: SettingsViewModel) {
    val navController = rememberNavController()
    val entry by navController.currentBackStackEntryAsState()
    val currentRoute = entry?.destination?.route ?: Routes.PREVIEW

    Scaffold(
        bottomBar = {
            NavigationBar {
                TABS.forEach { tab ->
                    val selected = entry?.destination?.hierarchy?.any { it.route == tab.route } == true
                        || currentRoute == tab.route
                    NavigationBarItem(
                        selected = selected,
                        onClick = {
                            if (currentRoute != tab.route) {
                                navController.navigate(tab.route) {
                                    popUpTo(Routes.PREVIEW) { saveState = true }
                                    launchSingleTop = true
                                    restoreState = true
                                }
                            }
                        },
                        icon = { Text(text = tab.icon) },
                        label = { Text(text = stringResource(id = tab.labelRes)) }
                    )
                }
            }
        }
    ) { padding ->
        NavHost(
            navController = navController,
            startDestination = Routes.PREVIEW,
            modifier = Modifier.padding(padding)
        ) {
            composable(Routes.PREVIEW) { PreviewScreen() }
            composable(Routes.DICTIONARY) { DictionaryScreen(viewModel = hiltViewModel()) }
            composable(Routes.SETTINGS) { SettingsScreen(viewModel = settingsVm) }
        }
    }
}